  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-alt: #f8fafc;
      --text: #102033;
      --muted: #5b6b7d;
      --border: #cfd8e3;
      --border-strong: #8ea0b5;
      --accent: #2457ff;
      --accent-hover: #1d46cc;
      --shadow: 0 18px 50px rgba(16, 32, 51, 0.12);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, #eaf1ff 0%, transparent 36%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      color: var(--text);
      line-height: 1.5;
    }

    a {
      color: inherit;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      background: var(--surface);
      border: 2px solid var(--accent);
      border-radius: 999px;
      transform: translateY(-200%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

