      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 640px);
      background: var(--surface);
      border: 1px solid rgba(207, 216, 227, 0.9);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: clamp(1.5rem, 3vw, 2.5rem);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.8rem, 3vw, 2.4rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .lede {
      margin: 0 0 1.75rem;
      color: var(--muted);
      max-width: 60ch;
    }

    .form-field {
      padding: 1.25rem;
      border: 1px solid var(--border);
      border-radius: calc(var(--radius) - 6px);
      background: linear-gradient(180deg, #ffffff 0%, var(--surface-alt) 100%);
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
      min-width: 0;
    }

    legend {
      padding: 0;
      font-weight: 700;
      font-size: 1.05rem;
      margin-bottom: 1rem;
    }

    .choices {
      display: grid;
      gap: 0.75rem;
    }

    .choice {
      display: flex;
      align-items: center;
      gap: 0.8rem;
      padding: 0.9rem 1rem;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 14px;
      transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
    }

    .choice:hover {
      border-color: var(--border-strong);
      transform: translateY(-1px);
    }

    .choice input {
      width: 1.1rem;
      height: 1.1rem;
      accent-color: var(--accent);
      margin: 0;
      flex: 0 0 auto;
    }

    .choice label {
      cursor: pointer;
      flex: 1;
      font-weight: 500;
    }

    .choice:has(input:focus-visible) {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(36, 87, 255, 0.16);
    }

    .choice:has(input:checked) {
      border-color: var(--accent);
      background: #eef3ff;
