      margin: 0.9rem 0 0;
      color: #a61b1b;
      font-weight: 600;
      min-height: 1.5rem;
    }

    .actions {
      margin-top: 1.5rem;
      display: flex;
      justify-content: flex-end;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.4rem;
      background: linear-gradient(180deg, var(--accent) 0%, #1d49e0 100%);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 10px 22px rgba(36, 87, 255, 0.22);
      transition: transform 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
    }

    button:hover {
      background: linear-gradient(180deg, #2f62ff 0%, var(--accent-hover) 100%);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid #1a3ea7;
      outline-offset: 3px;
    }

    @media (max-width: 480px) {
      .card {
        padding: 1.25rem;
      }

      .choice {
        padding: 0.85rem 0.9rem;
      }

      .actions {
        justify-content: stretch;
      }

      button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-alt: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --border: CanvasText;
        --border-strong: CanvasText;
        --accent: ButtonText;
        --accent-hover: ButtonText;
      }

      .skip-link,
      .card,
      .form-field,
      .choice,
      button {
        forced-color-adjust: auto;
      }

      .choice:has(input:focus-visible),
      button:focus-visible {
        outline-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content" class="page">
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Notification Preferences</h1>
      <p class="lede">Choose one way you want us to reach you when there is an update.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset>
            <legend>How do you prefer to receive notifications?</legend>

            <div class="choices" role="radiogroup" aria-describedby="form-error">
              <div class="choice">
                <input type="radio" id="notification-email" name="notification-preference" value="email" />
                <label for="notification-email">Email</label>
              </div>
              <div class="choice">
                <input type="radio" id="notification-sms" name="notification-preference" value="sms" />
                <label for="notification-sms">SMS</label>
              </div>
              <div class="choice">
                <input type="radio" id="notification-push" name="notification-preference" value="push" />
                <label for="notification-push">Push Notifications</label>
              </div>
            </div>

            <p id="form-error" class="error" aria-live="polite"></p>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit</button>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const errorMessage = document.getElementById('form-error');
    const radios = Array.from(form.querySelectorAll('input[type="radio"][name="notification-preference"]'));

    form.addEventListener('submit', (event) => {
      const selected = form.querySelector('input[type="radio"][name="notification-preference"]:checked');

      if (!selected) {
        event.preventDefault();
        errorMessage.textContent = 'Please choose one notification preference.';
        radios[0].focus();
        return;
      }

      event.preventDefault();
      errorMessage.textContent = `You selected ${selected.nextElementSibling.textContent}.`;
    });

    radios.forEach((radio) => {
      radio.addEventListener('change', () => {
        errorMessage.textContent = '';
      });
    });
  </script>
</body>
</html>
