   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content" class="page">
     <section class="card" aria-labelledby="page-title">
       <h1 id="page-title">Notification Preferences</h1>
       <p class="lede">Choose one way you want us to reach you when there is an update.</p>

       <form id="notification-form" novalidate>
         <div class="form-field">
           <fieldset aria-describedby="form-error">
             <legend>How do you prefer to receive notifications?</legend>

             <div class="choices">
               <div class="choice">
                 <input type="radio" id="notification-email" name="notification-preference" value="email" required />
                 <label for="notification-email">Email</label>
               </div>
               <div class="choice">
                 <input type="radio" id="notification-sms" name="notification-preference" value="sms" />
                 <label for="notification-sms">SMS</label>
               </div>
               <div class="choice">
                 <input type="radio" id="notification-push" name="notification-preference" value="push" />
                 <label for="notification-push">Push Notifications</label>
               </div>
             </div>

             <p id="form-error" class="error" aria-live="polite"></p>
           </fieldset>
         </div>

         <div class="actions">
           <button type="submit">Submit</button>
         </div>
       </form>
     </section>
